B.a1Q=new A.X(B.cp,["qibli_mosque","Qibli Mosque","Main prayer hall with a silver dome.","The Qibli Mosque is the southern building within Al-Aqsa, serving as the main congregational prayer hall. It faces the Qibla and is known for its large prayer space and historical architecture.",B.Xp,560,210,"Mosque"],t.yf)
B.VR=A.a(s(["assets/images/al_marwani.jpg"]),t.s)
B.a1R=new A.X(B.cp,["al_marwani","Al-Marwani Mosque","Underground mosque within Solomon's Stables.","Located in the southeastern corner of Al-Aqsa, Al-Marwani is an underground prayer hall built into a series of ancient vaults known as Solomon's Stables.",B.VR,540,440,"Mosque"],t.yf)
B.ZW=A.a(s(["assets/images/dome_chain.jpg"]),t.s)
B.a1S=new A.X(B.cp,["dome_chain","Dome of the Chain","Small dome next to Dome of the Rock.","The Dome of the Chain is a small open structure adjacent to the Dome of the Rock. Historically, it was a site of justice and preaching.",B.ZW,340,265,"Dome"],t.yf)
B.Yw=A.a(s(["assets/images/dome_ascension.jpg"]),t.s)
B.a1X=new A.X(B.cp,["dome_ascension","Dome of the Ascension","Commemorates the Prophet\u2019s ascension.","This small dome marks the traditional location from which the Prophet Muhammad ascended during the Isra and Mi\u2019raj. It is a symbol of this spiritual event.",B.Yw,300,150,"Dome"],t.yf)
B.SZ=A.a(s(["assets/images/dome_khalili.jpg"]),t.s)
B.a1T=new A.X(B.cp,["dome_khalili","Dome of al-Khalili","Small domed structure named after a sheikh.","This dome is named after Sheikh Khalili and is one of the small structures used for prayer and retreat within the compound.",B.SZ,175,145,"Dome"],t.yf)
