B.a1W=new A.X(B.cp,["dome_prophet","Dome of the Prophet","Commemorates the Prophet\u2019s prayer spot.","This dome is believed to mark the spot where the Prophet Muhammad led the previous prophets in prayer before ascending to the heavens.",B.Zv,310,170,"Dome"],t.yf)
